def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    rounds_left = 100 - n
    if rounds_left <= 1:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    my_c = 0
    for i in range(n):
        if op[i] == 'C':
            opp_c += 1
        if my[i] == 'C':
            my_c += 1
    my_def = n - my_c

    def coop_rate(start):
        cnt = 0
        tot = 0
        for i in range(start, n):
            tot += 1
            if op[i] == 'C':
                cnt += 1
        if tot == 0:
            return 0.5
        return cnt / tot

    r10 = coop_rate(n - 10 if n >= 10 else 0)

    opp_D = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_D += 1
        else:
            break

    opp_C = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            opp_C += 1
        else:
            break

    punish = 0
    forgive = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'D':
                punish += 1
            else:
                forgive += 1

    periodic = False
    if n >= 15:
        start = n - (20 if n >= 20 else n)
        tot = n - start
        if tot >= 15:
            for phase in range(5):
                matches = 0
                for i in range(start, n):
                    if ((i - start + phase) % 5) < 2:
                        exp = 'D'
                    else:
                        exp = 'C'
                    if op[i] == exp:
                        matches += 1
                if matches * 100 >= 90 * tot:
                    periodic = True
                    break

    if periodic:
        return 'D'

    last_me = my[-1]
    last_opp = op[-1]

    if last_opp == 'D':
        if opp_D <= 4 and r10 >= 0.5:
            return 'C'

        if n <= 15 and rounds_left > 5:
            if opp_D == 4 and last_me != 'C':
                return 'C'
            if opp_D == 5 and last_me == 'C':
                return 'C'

        return 'D'

    if n >= 2 and last_me == 'D' and op[-2] == 'D' and my[-2] == 'C':
        return 'C'

    if opp_c == n:
        if my_def == 0:
            if n >= 25 and rounds_left > 5 and rng.random() < 0.06:
                return 'D'
            return 'C'

        if rng.random() < 0.85:
            return 'D'
        return 'C'

    if forgive > punish and forgive >= 1 and r10 >= 0.55:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    if r10 >= 0.85 and opp_C >= 5 and rounds_left > 12:
        if rng.random() < 0.02:
            return 'D'
        return 'C'

    recent_len = 10 if n >= 10 else n
    recent_d = 0
    for i in range(n - recent_len, n):
        if op[i] == 'D':
            recent_d += 1

    if recent_d >= 3 and opp_C <= 2 and my_def == 0 and rounds_left > 8:
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    if rounds_left == 2 and r10 >= 0.75 and forgive > punish:
        return 'D'

    return 'C'
